new:
uniform float uBoss; // 0 trash, 1 elite/boss (heavier vocabulary)
// DEMOTION (BOSSES-V2 r3 minor). A boss fight draws TWO ground shapes at
// once: this shared disc, and the ASK silhouette that says which fight it
// is. The disc was winning — a dodge-the-lane capture led with a white ring
// and the lanes came second. When an ask silhouette is live the disc drops
// to a low-contrast BASE: the dark backing plate and the rim survive (they
// are the reach promise), the glow layers step aside.
uniform float uDemote;
varying vec2 vUv;
float telH(vec2 q) { return fract(sin(dot(floor(q), vec2(127.1, 311.7))) * 43758.5453); }

float glowA = (rimA * 1.1 + (fillA * 1.4 + sweep * 0.95 + runeA * 1.2 + innerA + commit * 0.2) * edgeF + fillGrad)
            * mix(1.0, 0.3, uDemote);
float darkA = (1.0 - smoothstep(0.88, 0.99, r)) * (0.24 + 0.16 * uProg);

tm.uniforms.uBoss.value = mon.kind === "boss" || mon.elite ? 1 : 0;
// The ASK silhouette outranks the shared disc while it is up (r3 minor).
tm.uniforms.uDemote.value =
  mon.kind === "boss" && this.bossFx.silhouetteLive ? 1 : 0;

/** 0..1 — the grip on bloom / light peaks / additive alpha this frame. */
exposureScale = 1;
/**
 * True while an ASK silhouette (lanes / cords / shell / props / cells / set)
 * is on the ground. The renderer demotes the shared telegraph disc while it
 * is, so the shape that says WHICH FIGHT THIS IS is the brightest element.
 */
silhouetteLive = false;

const dim = this.exposureScale;
this.silhouetteLive =
  this.shapes.some((b) => b.life < b.max) ||
  this.cords.some((c) => c.life < c.max) ||
  this.shells.some((sh) => sh.life < sh.max);
for (const b of this.beats) {

old:
float reach = smoothstep(uProg * 3.2 + 0.1, uProg * 3.2 - 0.14, along);
float fade = 1.0 - smoothstep(0.66, 1.0, uProg);
float a = clamp((body * 0.3 + wall * 0.9 + chev * 0.55) * reach * fade, 0.0, 0.82) * uDim;

new:
float reach = smoothstep(uProg * 3.2 + 0.1, uProg * 3.2 - 0.14, along);
float fade = 1.0 - smoothstep(0.66, 1.0, uProg);
// THE HUB IS CUT OUT (r3 minor). Folding by angle makes every bar's
// perpendicular distance collapse to zero at the middle, so N lanes merged
// into one soft star exactly where the eye lands — the shape doc calls for
// chevroned RECTANGLES and the mask was reading as an X. Punching the hub
// out separates the bars and the rectangles come back.
float hub = smoothstep(0.09, 0.24, r);
float a = clamp((body * 0.3 + wall * 0.9 + chev * 0.55) * reach * fade * hub, 0.0, 0.82) * uDim;
